@njit(cache=True)
def _rolling_zscore(values, window):
    n = values.shape[0]
    out = np.full(n, np.nan)
    for i in range(window - 1, n):
        w = values[i - window + 1 : i + 1]
        mu, sd = w.mean(), w.std()
        if sd > 0:
            out[i] = (values[i] - mu) / sd
    return out

